-- P09/P10: comparação explícita da referência PDF e da saída candidata congelada 80.
-- Não certifica populações equivalentes nem altera valores históricos.
WITH p AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=80 AND frozen AND status='ok' AND NOT truncated),
referencia AS(SELECT s->>'id' AS serie,v->>'rotulo' AS categoria,(v->>'valor')::numeric AS publicado FROM p CROSS JOIN LATERAL jsonb_array_elements(payload->'series') s CROSS JOIN LATERAL jsonb_array_elements(s->'valores') v WHERE s->>'id' LIKE 'regioes_%' OR s->>'id' LIKE 'sexo_por_regiao_%' OR s->>'id' IN('ufs','ufs_top_grafico','cidades')),
m AS(SELECT c->>'serie' AS serie,c->>'categoria' AS categoria,c->'atual' AS atual FROM p CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes') c WHERE c->>'serie' LIKE 'regioes_%' OR c->>'serie' LIKE 'sexo_por_regiao_%' OR c->>'serie' IN('ufs','ufs_top_grafico','cidades'))
SELECT m.serie,m.categoria,r.publicado AS pdf,(m.atual->>'valor')::numeric AS recalculado,(m.atual->>'contagem')::bigint AS contagem,(m.atual->>'denominador')::bigint AS denominador,round((m.atual->>'valor')::numeric-r.publicado,4) AS diferenca_pp,m.atual->>'fonte' AS fonte,m.atual->>'nota' AS nota,CASE WHEN r.publicado IS NULL THEN 'Categoria exclusiva do recálculo; sem referência PDF' ELSE 'Base atual e regras descritas; equivalência histórica em conciliação' END AS situacao FROM m LEFT JOIN referencia r USING(serie,categoria) ORDER BY m.serie,m.categoria
